let cart=[];try{const saved=JSON.parse(localStorage.getItem('respawn-cart')||'[]');if(Array.isArray(saved))cart=[...new Set(saved)].filter(id=>products.some(p=>p.id===id));}catch{}
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const grid=document.querySelector('#products');
let query='',sort='default';
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(filter='all'){
let list=products.filter(p=>(filter==='all'||p.category===filter)&&(p.name+' '+p.desc+' '+p.format).toLocaleLowerCase().includes(query));
if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));
document.querySelector('#results').textContent=`Найдено: ${list.length} из ${products.length}`;
grid.innerHTML=list.map(p=>`<article class="product"><div class="product-visual visual-${p.visual} ${p.image?'has-cover':''}">${p.image?`<img src="${p.image}" alt="${escapeHTML(p.name)}" loading="lazy" width="460" height="215">`:`<div class="brand-cover"><span>${p.type}</span><b>${p.label}</b><small>${p.format}</small></div>`}</div><div class="product-meta"><span>${p.type}</span><span>${p.format}</span></div><h3>${escapeHTML(p.name)}</h3><p>${p.desc}</p><a class="official" href="${p.url}" target="_blank" rel="noopener noreferrer">О товаре на официальном сайте ↗</a><div class="product-bottom"><div><small class="price-note">Пример цены</small><strong>${money(p.price)}</strong></div><button class="add" data-add="${p.id}" aria-label="Добавить ${escapeHTML(p.name)} в корзину">${cart.includes(p.id)?'В корзине ✓':'В корзину + '}</button></div></article>`).join('')||'<p class="empty-search">Ничего не найдено. Попробуйте другое название или категорию.</p>';
grid.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{const text=document.createElement('div');text.className='cover-fallback';text.textContent=img.alt;img.replaceWith(text);},{once:true}));
}
document.querySelector('#search').addEventListener('input',e=>{query=e.target.value.trim().toLocaleLowerCase();render(activeFilter);});
document.querySelector('#sort').addEventListener('change',e=>{sort=e.target.value;render(activeFilter);});
let activeFilter='all';document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{activeFilter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});render(activeFilter);}));
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300);}
function updateCart(){try{localStorage.setItem('respawn-cart',JSON.stringify(cart));}catch{}document.querySelector('#count').textContent=cart.length;document.querySelector('#cart-items').innerHTML=cart.length?cart.map(id=>{const p=products.find(p=>p.id===id);return `<div class="cart-row"><div>${p.name}<small>${p.format}</small></div><strong>${money(p.price)}</strong><button data-remove="${id}" aria-label="Удалить ${p.name}">×</button></div>`;}).join(''):'<p>Здесь пока пусто. Выберите игру или апгрейд для следующей сессии.</p>';document.querySelector('#total').textContent=money(cart.reduce((sum,id)=>sum+products.find(p=>p.id===id).price,0));render(activeFilter);}
grid.addEventListener('click',e=>{const button=e.target.closest('[data-add]');if(!button)return;const id=Number(button.dataset.add);if(cart.includes(id)){document.querySelector('#cart').showModal();return;}cart.push(id);updateCart();toast('Лут добавлен в корзину ✓');});
const dialog=document.querySelector('#cart');document.querySelector('#open-cart').onclick=()=>dialog.showModal();document.querySelector('#close-cart').onclick=()=>dialog.close();document.querySelector('#continue').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}const button=e.target.closest('[data-remove]');if(button){cart=cart.filter(id=>id!==Number(button.dataset.remove));updateCart();}});updateCart();
